import json,re,pathlib,importlib.util
ids=json.load(open('tasks/upgrade_tasks/coordination_20260927/batch3/assignment.json'))['batch']['papers']
print('MODULES',[(m,bool(importlib.util.find_spec(m))) for m in ['fitz','rdkit','ase','scipy']])
for pid in ids:
 d=(pathlib.Path('docs/evalution/update')/(pid+'.md')).read_text()
 print('\\n',pid)
 for l in d.splitlines():
